type fixtureStore struct {
 lister
 creator
 flags []*flipt.Flag
 segments []*flipt.Segment
 rules []*flipt.Rule
 createdAttachments []string
 createdRules int
 createdDistributions int
 createdConstraints int
}
func (s *fixtureStore) ListFlags(_ context.Context, _ ...storage.QueryOption) ([]*flipt.Flag,error) { return s.flags,nil }
func (s *fixtureStore) ListSegments(_ context.Context, _ ...storage.QueryOption) ([]*flipt.Segment,error) { return s.segments,nil }
func (s *fixtureStore) ListRules(_ context.Context, _ string, _ ...storage.QueryOption) ([]*flipt.Rule,error) { return s.rules,nil }
