func (s *fixtureStore) CreateVariant(_ context.Context, r *flipt.CreateVariantRequest) (*flipt.Variant,error) { s.createdAttachments=append(s.createdAttachments,r.Attachment); return &flipt.Variant{Id:\"variant-id\",Key:r.Key},nil }
func (s *fixtureStore) CreateSegment(_ context.Context, r *flipt.CreateSegmentRequest) (*flipt.Segment,error) { return &flipt.Segment{Key:r.Key},nil }
func (s *fixtureStore) CreateConstraint(_ context.Context, _ *flipt.CreateConstraintRequest) (*flipt.Constraint,error) { s.createdConstraints++; return &flipt.Constraint{},nil }
func (s *fixtureStore) CreateRule(_ context.Context, _ *flipt.CreateRuleRequest) (*flipt.Rule,error) { s.createdRules++; return &flipt.Rule{Id:\"rule-id\"},nil }
func (s *fixtureStore) CreateDistribution(_ context.Context, _ *flipt.CreateDistributionRequest) (*flipt.Distribution,error) { s.createdDistributions++; return &flipt.Distribution{},nil }

func TestExportAttachmentAsYAMLStructure(t *testing.T) {
 s:= &fixtureStore{flags:[]*flipt.Flag{{Key:\"flag\",Variants:[]*flipt.Variant{{Key:\"variant\",Attachment:"'`{"items":[1,true,null,{"name":"hello"}]}`}}}}}
 var out bytes.Buffer
 if err:=NewExporter(s).Export(context.Background(),&out); err!=nil { t.Fatal(err) }
 var doc map[interface{}]interface{}
 if err:=yaml.Unmarshal(out.Bytes(),&doc); err!=nil { t.Fatal(err) }
 flags:=doc["flags"].([]interface{})
 variants:=flags[0].(map[interface{}]interface{})["variants"].([]interface{})
 attachment:=variants[0].(map[interface{}]interface{})["attachment"].(map[interface{}]interface{})
 items:=attachment["items"].([]interface{})
 if len(items)!=4 || items[0]!=1 || items[1]!=true || items[2]!=nil || items[3].(map[interface{}]interface{})["name"]!="hello" { t.Fatalf("unexpected attachment: %#v",attachment) }
}
func TestImportYAMLAttachmentAndRelationships(t *testing.T) {
 input:=`flags:
- key: flag
  variants:
  - key: variant
    attachment:
      items: [1, true, null, {name: hello}]
  rules:
  - segment: segment
    rank: 1
    distributions:
    - variant: variant
      rollout: 50
segments:
- key: segment
  constraints:
  - type: STRING_COMPARISON_TYPE
    property: country
    operator: eq
    value: US
`
 s:=&fixtureStore{}
 if err:=NewImporter(s).Import(context.Background(),bytes.NewBufferString(input)); err!=nil { t.Fatal(err) }
 var got map[string]interface{}
 if err:=json.Unmarshal([]byte(s.createdAttachments[0]),&got); err!=nil { t.Fatal(err) }
 items:=got["items"].([]interface{})
 if len(items)!=4 || items[0]!=float64(1) || items[1]!=true || items[2]!=nil || items[3].(map[string]interface{})["name"]!="hello" { t.Fatalf("unexpected attachment: %#v",got) }
 if s.createdRules!=1 || s.createdDistributions!=1 || s.createdConstraints!=1 { t.Fatalf("missing relationships: %+v",s) }
}
func TestImportMissingAttachment(t *testing.T) {
 s:=&fixtureStore{}
 if err:=NewImporter(s).Import(context.Background(),bytes.NewBufferString("flags:'"\\n- key: flag\\n  variants:\\n  - key: variant\\n\"));err"'!=nil { t.Fatal(err) }
 if len(s.createdAttachments)!=1 || s.createdAttachments[0]!="" { t.Fatalf("attachment = %#v",s.createdAttachments) }
}
EOF
